    /*
     * Add to the SerialNumbers
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	InventoryItem
     */
    public InventoryItem addToSerialNumbers( UUID parentId, SerialNumber addTo ) {
	    LOGGER.info("handling AssignSerialNumbersToInventoryItemEvent - " );
	    
	    InventoryItem parentEntity = repository.findById(parentId).get();
	    SerialNumber child = registry.project( SerialNumber.class, addTo.getSerialNumberId());
	    
	    parentEntity.getSerialNumbers().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

